  "claims": [
    {
      "id": "r:5141721593",
      "kind": "correctness",
      "harm": "The fuzz harness aborts on random input due to libsecp256k1 illegal argument assertions when passing never-generated secnonces, breaking oss-fuzz runs",
      "quote": "The target aborts on 8 of 1000 files, with `[libsecp256k1] illegal argument: secp256k1_memcmp_var(&secnonce->data[0], secp256k1_musig_secnonce_magic, 4) == 0`.",
      "blocking": true,
      "status": "resolved",
      "author_replies": [
        "c:5592876523",
        "c:5593029949"
      ],
      "fix_pushed": true,
      "settled_by_id": "c:5592876523",
      "settled_by_quote": "Yes, I think this is a better approach. I've dropped that call from this harness."
    },
    {
      "id": "rc:3957935776",
      "kind": "usefulness",
      "harm": "Multi-participant signing and signature aggregation paths are virtually unreachable when feeding arbitrary random bytes as nonce points",
      "quote": "These bytes are almost never a valid pair of nonce points, so a session with more than one participant almost always stops before signing.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:3962910144",
        "c:5593029949"
      ],
      "fix_pushed": true,
      "settled_by_id": "rc:3962910144",
      "settled_by_quote": "Ahh, makes sense, thanks! I think I've understood and taken your suggestions."
    }
  ],
  "support": [
    {
      "id": "r:5141721593",
      "verdict": "Concept ACK",
      "reason": "The four signing functions in the module have no unit test today, only the `wallet_musig.py` functional test, so the harness covers ground that was empty.",
      "substantive": true
    }
  ],
  "notes": "First read. jeanpablojp offered Concept ACK while raising two harness concerns (libsecp256k1 assertion aborts and unreachable aggregation paths), both of which nervana21 promptly addressed with code updates."
}
